1	// One acquisition pass: for each due source module, fetch what is missing, put the
2	// verbatim payload in the raw cache, and only then let a parser near it.
3	//
4	// A source that fails is a signal for a human, not a broken pipeline — the pass records
5	// the reason, keeps going, and finishes successfully with a report.
6	import type { AnalysisMessage, Queue, R2Bucket } from '../env.ts';
7	import type { Corpus, ExtractedStatement } from '../corpus/store.ts';
8	import { fetchPage, type FetchDeps, type FetchFailure, type FetchOptions } from './fetcher.ts';
9	import type { SourceModule, SourceRegistry, RawStatement } from './registry.ts';
10	import type { RosterEntry } from '../corpus/roster.ts';
11	
12	export type ItemFailure = { key: string; url: string; reason: FetchFailure | 'extraction'; detail: string };
13	
14	export type ModuleOutcome = {
15	  module: string;
16	  fetched: number;
17	  /** Already in the cache and already extracted: no request was issued. */
18	  skipped: number;
19	  statements: number;
20	  /** Passages held for a decision because we do not track their speaker. */
21	  unattributed: number;
22	  failures: ItemFailure[];
23	};
24	
25	export type AcquisitionOptions = {
26	  corpus: Corpus;
27	  raw: R2Bucket;
28	  queue: Queue<AnalysisMessage>;
29	  registry: SourceRegistry;
30	  /** Who we track. An input to the pass, never something the pass adds to. */
31	  roster: RosterEntry[];
32	  deps: FetchDeps;
33	  now: () => string;
34	  /** Re-fetch documents already in the cache — the only way a changed page is re-read. */
35	  force?: boolean;
36	  fetch?: FetchOptions;
37	};
38	
39	const rawKeyFor = (module: SourceModule, document: { key: string }, fetchedAt: string): string =>
40	  `${module.id}/${encodeURIComponent(document.key)}/${fetchedAt}.raw`;
41	
42	export async function runAcquisition(options: AcquisitionOptions): Promise<ModuleOutcome[]> {
43	  const outcomes: ModuleOutcome[] = [];
44	  for (const module of options.registry.all()) {
45	    outcomes.push(await runModule(module, options));
46	  }
47	  return outcomes;
48	}
49	
50	async function runModule(module: SourceModule, options: AcquisitionOptions): Promise<ModuleOutcome> {
51	  const outcome: ModuleOutcome = { module: module.id, fetched: 0, skipped: 0, statements: 0, unattributed: 0, failures: [] };
52	  const documents = await module.list();
53	
54	  for (const document of documents) {
55	    const known = await options.corpus.findSource(module.id, document.key);
56	    if (known?.extraction === 'extracted' && !options.force) {
57	      outcome.skipped += 1;
58	      continue;
59	    }
60	
61	    const result = await fetchPage(document.url, options.deps, options.fetch);
62	    if (!result.ok) {
63	      outcome.failures.push({ key: document.key, url: document.url, reason: result.reason, detail: result.detail });
64	      // Durable, so a blocked source reads as blocked rather than as a source that has
65	      // never said anything. It is not marked extracted, so the next pass tries again.
66	      await options.corpus.recordSource({
67	        url: document.url,
68	        publisher: module.publisher,
69	        kind: module.kind,
70	        fetchedAt: options.now(),
71	        rawKey: '',
72	        extraction: result.reason === 'blocked' ? 'blocked' : 'failed',
73	        sourceModule: module.id,
74	        externalKey: document.key,
75	      });
76	      continue;
77	    }
78	
79	    const fetchedAt = options.now();
80	    const rawKey = rawKeyFor(module, document, fetchedAt);
81	    // Before anything interprets it: a payload that crashes the parser is still on disk
82	    // to debug against, and a parser fix replays from here without a request.
83	    await options.raw.put(rawKey, result.body);
84	
85	    const source = await options.corpus.recordSource({
86	      url: document.url,
87	      publisher: module.publisher,
88	      kind: module.kind,
89	      fetchedAt,
90	      rawKey,
91	      extraction: 'pending',
92	      sourceModule: module.id,
93	      externalKey: document.key,
94	    });
95	    outcome.fetched += 1;
96	
97	    try {
98	      const saved = await extractInto(options, module, source.id, result.body, document);
99	      outcome.statements += saved.statements;
100	      outcome.unattributed += saved.unattributed;
101	    } catch (error) {
102	      await options.corpus.setExtractionStatus(source.id, 'failed');
103	      outcome.failures.push({ key: document.key, url: document.url, reason: 'extraction', detail: String(error) });
104	    }
105	  }
106	  return outcome;
107	}
108	
109	/**
110	 * Turn one payload into statements and hand each to analysis.
111	 *
112	 * A speaker the roster does not name is neither dropped nor promoted: the passage is held
113	 * unattributed, under the name the document wrote, for a person to decide about (#31).
114	 * Acquisition cannot create a figure — that is the whole of the fix, and the reason this
115	 * function takes the roster rather than reaching for a corpus method that mints one.
116	 */
117	async function extractInto(
118	  options: Pick<AcquisitionOptions, 'corpus' | 'queue' | 'roster'>,
119	  module: SourceModule,
120	  sourceId: string,
121	  payload: string,
122	  document: { key: string; url: string },
123	): Promise<{ statements: number; unattributed: number }> {
124	  const rawStatements: RawStatement[] = module.extract(payload, document);
125	  const extracted: ExtractedStatement[] = [];
126	  let held = 0;
127	
128	  for (const raw of rawStatements) {
129	    const figure = await options.corpus.resolveSpeaker(options.roster, raw.speaker.displayName);
130	    if (!figure) {
131	      // Its ordinal goes with it, so the statements that did resolve keep the positions
132	      // they had in the payload and adding this speaker later moves nobody's id.
133	      await options.corpus.recordUnattributed(sourceId, {
134	        speakerName: raw.speaker.displayName,
135	        speakerRole: raw.speaker.role,
136	        ordinal: raw.ordinal,
137	        quote: raw.quote,
138	        language: raw.language,
139	        saidAt: raw.saidAt,
140	        context: raw.context,
141	      });
142	      held += 1;
143	      continue;
144	    }
145	    extracted.push({
146	      ordinal: raw.ordinal,
147	      figureId: figure.id,
148	      quote: raw.quote,
149	      language: raw.language,
150	      saidAt: raw.saidAt,
151	      context: raw.context,
152	      topics: raw.topics,
153	    });
154	  }
155	
156	  const saved = await options.corpus.saveStatements(sourceId, extracted);
157	  await options.corpus.setExtractionStatus(sourceId, 'extracted');
158	  for (const statement of saved) await options.queue.send({ statementId: statement.id });
159	  return { statements: saved.length, unattributed: held };
160	}
161	
162	/**
163	 * Re-run an extractor over a payload already in the cache. This is what a parser fix
164	 * costs: no request, no dependence on a site that has since changed or died. The
165	 * statements keep the ids they were given the first time.
166	 */
167	export async function reextract(
168	  options: Pick<AcquisitionOptions, 'corpus' | 'raw' | 'queue' | 'registry' | 'roster'>,
169	  sourceId: string,
170	): Promise<{ statements: number; unattributed: number }> {
171	  const record = await options.corpus.getSourceRecord(sourceId);
172	  if (!record) throw new Error(`no such source: ${sourceId}`);
173	  const module = options.registry.get(record.sourceModule);
174	  if (!module) throw new Error(`source ${sourceId} was written by ${record.sourceModule}, which is not registered`);
175	  const object = await options.raw.get(record.source.rawKey);
176	  if (!object) throw new Error(`raw payload ${record.source.rawKey} is not in the cache`);
177	  return extractInto(options, module, sourceId, await object.text(), {
178	    key: record.externalKey,
179	    url: record.source.url,
180	  });
181	}

